mapper.select:
SELECT created_at
FROM diary
WHERE user_id = #{userId}
AND YEAR(created_at) = #{year}

SELECT id, user_id, title, CASE WHEN CHAR_LENGTH(content) > 100 THEN CONCAT(SUBSTRING(content, 1, 100), '......') ELSE content END AS content, is_public, status, view_count, like_count, is_deleted, created_at, updated_at FROM diary WHERE is_deleted = false
AND user_id = #{userId}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND is_public = true
ORDER BY created_at DESC LIMIT #{offset}, #{limit}
